window.DATA_REGISTRI = [{"paese": "Afghanistan", "registro": "https://acdr.af/", "background": "ADR commerciale regolato dalla Commercial Mediation Law 2007; l'Afghanistan Center for Commercial Dispute Resolution (ACDR), presso la Camera di Commercio, offre mediazione e arbitrato e tiene liste di mediatori/arbitri. Non esiste un registro statale pubblico online."}, {"paese": "Albania", "registro": "https://www.drejtesia.gov.al/", "background": "Mediazione (ndërmjetësim) regolata dalla legge 10385/2011: il mediatore è iscritto in un registro presso il Ministero della Giustizia. Richiesti laurea, formazione specifica ed esame di abilitazione; provenienza spesso giuridica o socio-assistenziale."}, {"paese": "Algeria", "registro": "https://www.mjustice.gov.dz/", "background": "Médiation judiciaire prevista dal codice di procedura civile e amministrativa; il mediatore presenta domanda al Procuratore presso la Corte d'appello e le liste sono approvate con decreto del Ministro della Giustizia."}, {"paese": "Andorra", "registro": "https://www.govern.ad/ca/ministeris-i-secretaries-d-estat/ministeri-de-justicia-i-interior/area-d-entitats-juridiques-i-professions-titulades/registre-de-mediadors", "background": "La legge 3/2018 istituisce il mediatore e un registro pubblico presso il Ministero della Giustizia; richieste formazione specifica e formazione continua (regolamento 2019)."}, {"paese": "Angola", "registro": "http://www.servicos.minjusdh.gov.ao/outros-servicos-ao-cidadao/41/resolucao-extrajudicial-de-litigios", "background": "Mediazione e conciliazione regolate dalla Lei 12/16 del 12 agosto 2016; il mediatore è terzo imparziale con esperienza o formazione certificata, operante nei centri di risoluzione extragiudiziale del Ministero della Giustizia."}, {"paese": "Antigua e Barbuda", "registro": "https://www.eccourts.org/", "background": "Court-connected mediation amministrata dalla Eastern Caribbean Supreme Court, che tiene un Roster di mediatori approvati dal Mediation Committee, soggetti a un codice etico."}, {"paese": "Arabia Saudita", "registro": "https://sadr.org/neutrals/mediators", "background": "Mediazione commerciale gestita dal Saudi Center for Commercial Arbitration (SADR/SCCA); per entrare nella lista occorre un corso del Centro, esperienza pratica e iscrizione. Candidati tipicamente giuristi e professionisti d'affari."}, {"paese": "Argentina", "registro": "https://www.argentina.gob.ar/justicia/mediacion/mediadores", "background": "Mediazione prejudiziale obbligatoria; la Dirección Nacional de Mediación (Ministero della Giustizia) tiene il Registro Nacional de Mediadores. Serve essere avvocato con anni di esercizio, formazione e valutazione di idoneità; elenco pubblico."}, {"paese": "Armenia", "registro": "https://amca.am/en/public/list_universal/id/24", "background": "Il mediatore autorizzato deve avere oltre 25 anni, laurea e superare un programma di formazione del Ministero della Giustizia; iscritto nel registro ufficiale. Opera anche l'Arbitration and Mediation Center of Armenia (AMCA)."}, {"paese": "Australia", "registro": "https://amdras.au/mediators/", "background": "Accreditamento secondo l'AMDRAS (dal 1° luglio 2025, in sostituzione del NMAS), sotto il Mediator Standards Board; formazione e valutazione presso i Recognised Accreditation Providers; iscrizione al National Register of Accredited Mediators."}, {"paese": "Austria", "registro": "https://justizonline.gv.at/jop/web/mediatoren/mediatorensuche", "background": "Il Ministero federale della Giustizia tiene dal 2004 la Mediatorenliste per la mediazione civile; richiesti 28 anni, formazione riconosciuta (centinaia di ore) e assicurazione RC (min. 400.000 €). Iscrizione max 5 anni, prorogabile."}, {"paese": "Azerbaigian", "registro": "http://mediasiya.gov.az/mediasiya-reyestri/mediasiya-teskilatlari", "background": "Legge sulla mediazione 1555-VQ del 2019; il Consiglio di mediazione (presso il Ministero della Giustizia) tiene il registro di mediatori, organizzazioni ed enti di formazione. Richiesti istruzione superiore, 25 anni, designazione da un'organizzazione ed esame."}, {"paese": "Bahamas", "registro": "https://courts.bs/practice-directions/", "background": "Mediazione poco diffusa e court-connected in fase di implementazione; nessun albo strutturato. Il mediatore può essere un professionista formato, un avvocato esperto o un giudice in pensione."}, {"paese": "Bahrain", "registro": "https://bcdr.org/", "background": "Mediazione regolata dal D.lgs. 22/2019; mediatore scelto dalle parti o certificato presso il Ministero della Giustizia. La Bahrain Chamber for Dispute Resolution (BCDR) tiene un elenco di mediatori accreditati per settori."}, {"paese": "Bangladesh", "registro": "https://biac.org.bd/", "background": "Il Bangladesh International Arbitration Centre (BIAC) tiene un panel di mediatori accreditati (commerciale, edilizio, bancario, immobiliare) secondo le BIAC Mediation Rules; mediatori con background legale e professionale."}, {"paese": "Barbados", "registro": "https://www.barbadoslawcourts.gov.bb/court-administration/court-projects/initiatives/court-annexed-mediation-pilot-project/", "background": "Mediazione regolata dal Mediation Act 2015; mediatori selezionati da un Roster della Supreme Court tra soggetti formati e certificati (CEDR o titoli accademici). Opera anche l'ADR Association of Barbados."}, {"paese": "Belgio", "registro": "https://search-fbcfm.just.fgov.be/cgi-bemed/liste-mediateur.pl?lg=fr", "background": "L'accreditamento è obbligatorio: la Commission fédérale de médiation (presso il SPF Justice) riconosce i mediatori e ne tiene il registro pubblico. Richiesta formazione riconosciuta; settori familiare, civile/commerciale e sociale."}, {"paese": "Belize", "registro": "https://www.belizejudiciary.org/court-connected-mediators/", "background": "La magistratura tiene un elenco di mediatori court-connected presso la Supreme Court (Civil Procedure Rules); mediatori formati e accreditati inseriti nel roster giudiziario."}, {"paese": "Benin", "registro": "https://cci.bj/arbitrage-mediation", "background": "Mediazione inquadrata nell'Atto uniforme OHADA (2017); il CAMeC-CCIB (Camera di Commercio, Cotonou) tiene un elenco di mediatori e arbitri accreditati e organizza formazione. Provenienza giuridica ed economico-imprenditoriale."}, {"paese": "Bhutan", "registro": "https://bnli.bt/", "background": "Mediazione formalizzata dall'Alternative Dispute Resolution Act 2013; il Bhutan National Legal Institute forma i mediatori; la Court-Annexed Mediation Unit opera con mediatori giudiziari formati, gratuiti, con codice di condotta."}, {"paese": "Bielorussia", "registro": "https://minjust.gov.by/directions/advocacy/mediation/list_register/", "background": "Il Ministero della Giustizia tiene il Registro dei mediatori e quello delle organizzazioni di mediazione. Richiesti istruzione superiore, corso di formazione, esame di qualificazione e certificato ministeriale."}, {"paese": "Bolivia", "registro": "https://minjusdh.libguides.com/cejdh/ence", "background": "Conciliazione extragiudiziale regolata dalla Legge 708/2015; il Ministero della Giustizia autorizza e registra i Centri di conciliazione. Conciliatori con formazione di almeno 40 ore; per le materie giuridiche titolo in diritto (ENCE)."}, {"paese": "Bosnia ed Erzegovina", "registro": "https://www.umbih.ba/index.php/medijacija/lista-medijatora", "background": "Il Registro dei mediatori è tenuto dall'Associazione dei mediatori (UMBiH) secondo il regolamento (G.U. BiH 21/06) e la legge sulla mediazione; richiesti cittadinanza, titolo di studio e certificato di formazione."}, {"paese": "Botswana", "registro": "https://www.gov.bw/industrial-court/court-annex-mediation", "background": "Mediazione court-annexed introdotta con le High Court Rules (42A) e presso l'Industrial Court; nessun registro pubblico online, arruolamento tramite l'Ufficio del Registrar."}, {"paese": "Brasile", "registro": "https://www.cnj.jus.br/programas-e-acoes/conciliacao-e-mediacao/quero-ser-um-conciliador-mediador/", "background": "Il CNJ gestisce il Cadastro Nacional de Mediadores Judiciais e Conciliadores. Per il mediatore giudiziale: laurea da almeno due anni (L. 13.140/2015) e corso riconosciuto (Ris. CNJ 125/2010); ai conciliatori non si applica il requisito della laurea."}, {"paese": "Brunei", "registro": "https://www.bdac.com.bn/", "background": "Mediazione presso il Brunei Darussalam Arbitration Centre (BDAC), il Brunei Mediation Centre e i tribunali subordinati; il BDAC accredita i mediatori con propri corsi. Nessun registro pubblico con requisiti standardizzati per legge."}, {"paese": "Bulgaria", "registro": "https://mediation.mjs.bg/Register/Mediators", "background": "Il Ministero della Giustizia tiene il Registro Unico dei Mediatori, necessario per esercitare; richiesto un corso di formazione superato, poi certificato ministeriale entro 30 giorni."}, {"paese": "Burkina Faso", "registro": "https://www.camco.bf/mediation/", "background": "Mediazione commerciale gestita dal CAMC-O (Camera di Commercio, Ouagadougou, 2005), che recluta e accredita mediatori tramite bandi per procedure OHADA e internazionali."}, {"paese": "Burundi", "registro": "", "background": "Mediazione e arbitrato commerciale presso il Centre Burundais d'Arbitrage et de Conciliation (CEBAC), Bujumbura. Nessun registro ufficiale online né dati affidabili su requisiti e accreditamento."}, {"paese": "Cambogia", "registro": "https://ncac.org.kh/en/services/mediation/list-of-mediators/", "background": "Il National Commercial Arbitration Centre (NCAC), sostenuto dai Ministeri del Commercio e della Giustizia, pubblica la lista dei mediatori. Operano anche il Cambodia Centre for Mediation e l'Arbitration Council (lavoro); mediatori accreditati con background giuridico/professionale."}, {"paese": "Camerun", "registro": "https://legecam.cm/cmag/", "background": "Nessun albo pubblico obbligatorio; mediazione ex Atto uniforme OHADA 2017. Il Centre de Médiation et d'Arbitrage du GICAM (CMAG) gestisce una lista aperta di mediatori (appello a candidature); centri anche presso la CCIMA. Formazione dai centri."}, {"paese": "Canada", "registro": "https://adric.ca/professional-designations/mediator-designations/", "background": "Mediazione regolata a livello provinciale, nessun albo statale unico; l'ADR Institute of Canada (ADRIC), con gli istituti provinciali, rilascia le designazioni Qualified Mediator (Q.Med) e Chartered Mediator (C.Med). In Ontario opera l'Ontario Mandatory Mediation Program con un roster."}, {"paese": "Capo Verde", "registro": "https://justica.gov.cv/", "background": "Dal 2026 istituiti il Registo Nacional dos Centros de Mediação e Arbitragem e la Lista Oficial Nacional de Mediadores (piattaforma digitale pubblica del dipartimento Giustizia), con qualifiche ed esperienza; centri soggetti ad autorizzazione preventiva e a una Commissione Nazionale di Etica. Provenienza tipicamente giuridica con formazione specialistica."}, {"paese": "Ciad", "registro": "https://www.ohada.com/etats-membres/tchad.html", "background": "Membro OHADA, applica l'Atto uniforme sulla mediazione 2017: le parti scelgono liberamente il mediatore, anche con un'autorità di nomina. Esiste un Médiateur de la République (ombudsman), figura distinta. Mancano dati su formazione/accreditamento nazionali."}, {"paese": "Cile", "registro": "https://www.mediacionchile.gob.cl/registro-de-mediadores/", "background": "Registro de Mediadores unico nazionale del Ministerio de Justicia (art. 112 L. 19.968), soprattutto per la mediazione familiare; richiesti titolo/diploma in mediazione e famiglia (≥180 ore teoriche + 40 di pratica), assenza di condanne e sede idonea."}, {"paese": "Cina", "registro": "https://www.moj.gov.cn/zwfw/zwfwbszn/bsznrmtj/", "background": "Mediazione popolare (人民调解) regolata dal Ministero della Giustizia; mediatori cittadini retti e imparziali con conoscenze giuridiche (avvocati, notai, arbitri, medici, insegnanti, giudici/procuratori in pensione). I dipartimenti giudiziari locali pubblicano gli elenchi."}, {"paese": "Cipro", "registro": "https://www.gov.cy/mjpo/en/justice-sector/legal-affairs-unit/mediation/", "background": "Registro dei Mediatori tenuto dal Ministry of Justice and Public Order; per le controversie commerciali serve essere avvocato o membro di camera/ordine, laureato, con 40 ore di formazione; aggiornamento continuo di 24 ore ogni tre anni."}, {"paese": "Colombia", "registro": "https://www.sicaac.gov.co/", "background": "Il SICAAC del Ministerio de Justicia registra centri di conciliazione, conciliatori, arbitri e procedure. La figura tipica è il conciliador (spesso avvocato) formato e accreditato presso un centro autorizzato."}, {"paese": "Comore", "registro": "https://www.ohada.org", "background": "Membro OHADA, applica l'Atto uniforme sulla mediazione (2017): le parti scelgono di comune accordo il mediatore, eventualmente con un'autorità di nomina. Mancano registro pubblico e dati su formazione/accreditamento."}, {"paese": "Congo", "registro": "https://liziba.cg/en/cemaco/", "background": "Il Centre de Médiation et d'Arbitrage du Congo (CEMACO, 2012, Camere di commercio) gestisce le controversie commerciali secondo il diritto OHADA; mediatori scelti dalle parti dagli elenchi del Centro, senza albo pubblico obbligatorio."}, {"paese": "Corea del Nord", "registro": "", "background": "Nessun albo di mediatori né mediazione civile strutturata. Per le controversie economiche estere opera un organo arbitrale (legge 1999) che può ricorrere alla conciliazione, senza mediatori accreditati."}, {"paese": "Corea del Sud", "registro": "https://www.kcab.or.kr/", "background": "Mediazione soprattutto giudiziale (조정): mediatori sono giudici o commissari di conciliazione nominati dai tribunali tra avvocati, ex giudici, professori e professionisti. Per il commerciale opera il KCAB."}, {"paese": "Costa d'Avorio", "registro": "http://www.courarbitrage.ci/mediation/", "background": "Mediazione commerciale (legge 2014) amministrata dalla Cour d'Arbitrage de Côte d'Ivoire (CACI) presso la Camera di Commercio; mediatori formati, indipendenti e imparziali. Si applica anche l'OHADA 2017."}, {"paese": "Costa Rica", "registro": "https://www.mjp.go.cr/viceministeriopaz/DepenDinarac?nom=centros", "background": "Materia regolata dalla Legge RAC 7727; la DINARAC (Ministero di Giustizia e Pace) autorizza i centri e approva i neutrali nelle liste. Mediatori con certificazione di un centro autorizzato."}, {"paese": "Croazia", "registro": "https://mpudt.gov.hr/", "background": "Il Ministero della Giustizia tiene il Registro degli izmiritelja su base volontaria; iscrizione con formazione base di almeno 40 ore presso ente accreditato ed esame (legge sulla mediazione NN 18/11)."}, {"paese": "Cuba", "registro": "https://www.camaracuba.cu/ccaci", "background": "Mediazione regolata dal Decreto-Legge 69/2023; per il commerciale opera la Corte Cubana di Arbitrato Commerciale Internazionale con una lista di mediatori. Richiesti laurea in Diritto, Psicologia o Sociologia e corso di certificazione."}, {"paese": "Danimarca", "registro": "https://mediationsinstituttet.dk/", "background": "Nessun albo statale; mediatori privati soprattutto avvocati-mediatori formati da Danske Advokater e riconosciuti dal Mediationsinstituttet. Nei tribunali opera la retsmægling con giudici o avvocati."}, {"paese": "Dominica", "registro": "https://www.eccourts.org/court-connected-mediation", "background": "Mediazione court-connected gestita dalla Eastern Caribbean Supreme Court (comune agli Stati OECS); mediatori formati inseriti nel Roster dell'ECSC."}, {"paese": "Ecuador", "registro": "https://www.funcionjudicial.gob.ec/registro-centros-mediacion/", "background": "Il Consejo de la Judicatura registra i centri di mediazione (Legge di Arbitrato e Mediazione) e i mediatori abilitati, che devono avere formazione specifica e certificato di habilitación."}, {"paese": "Egitto", "registro": "https://crcica.org/", "background": "Nessun albo nazionale unico; mediazione commerciale amministrata da centri come il Cairo Regional Centre for International Commercial Arbitration (CRCICA). Mediatori avvocati o esperti certificati dal Ministero della Giustizia o dai centri."}, {"paese": "El Salvador", "registro": "https://pgr.gob.sv/index.php/m-servicios/m-udmccm", "background": "La Procuraduría General de la República, tramite la UDMCCM, accredita mediatori e centri e tiene il Registro Nacional de Mediadores Acreditados; formazione e accreditamento della PGR."}, {"paese": "Emirati Arabi Uniti", "registro": "https://u.ae/en/information-and-services/justice-safety-and-the-law/litigation-procedures/mediation", "background": "D.lgs. federale 40/2023; mediatori scelti da liste di esperti registrati presso il Ministero della Giustizia o le autorità locali (es. Abu Dhabi Judicial Department), previa formazione (Abu Dhabi Judicial Academy) e approvazione del comitato."}, {"paese": "Eritrea", "registro": "", "background": "Nessun registro professionale; controversie risolte per lo più con meccanismi tradizionali (shimglna: anziani, capi religiosi/comunitari) e community courts (proclamazione 2003)."}, {"paese": "Estonia", "registro": "https://lepitus.ee/", "background": "Nessun albo statale generale; la mediazione familiare fa capo all'Eesti Lepitajate Ühing, che forma e qualifica i mediatori. La legge sulla conciliazione consente ad avvocati e notai di operare come conciliatori."}, {"paese": "Eswatini", "registro": "https://www.cmac.org.sz/", "background": "La Conciliation, Mediation and Arbitration Commission (CMAC), ente pubblico (Industrial Relations Act 2000), gestisce conciliazione e mediazione soprattutto nel lavoro; per il civile opera la court-annexed mediation."}, {"paese": "Etiopia", "registro": "", "background": "La Proclamazione 1234/2021 e la Direttiva 12/2022 hanno istituito la mediazione annessa ai tribunali federali; mediatori nominati dalle parti o dalla corte. Operano centri come AACCSA e EMAC. Nessun registro pubblico online."}, {"paese": "Figi", "registro": "https://fijimediation.org/", "background": "Mediazione offerta dal Fiji Mediation Centre (FMC), con un panel di mediatori spesso accreditati dal Singapore Mediation Centre; esiste anche la mediazione presso i tribunali. Nessun albo statale unico."}, {"paese": "Filippine", "registro": "https://philja.judiciary.gov.ph/", "background": "Il Philippine Mediation Center Office (PMCO), sotto la PHILJA della Corte Suprema, recluta, forma e accredita i mediatori per la Court-Annexed Mediation (accreditamento rinnovabile). Per la PI esiste un roster presso l'IPOPHL."}, {"paese": "Finlandia", "registro": "https://thl.fi", "background": "Mediazione giudiziale (tuomioistuinsovittelu) condotta dai giudici, senza albo separato; mediazione penale e civile comunitaria coordinata dall'Istituto per la salute e il benessere (THL). Nessun registro pubblico di mediatori."}, {"paese": "Francia", "registro": "https://www.justice.gouv.fr/actualites/actualite/liste-mediateurs-aupres-cour-dappel", "background": "Ogni Corte d'Appello redige (decreto 2017-1457) una lista di mediatori valida tre anni, informativa per i giudici. Per i consumatori i mediatori sono iscritti dalla CECMC; il Conseil National de la Médiation (2023) fissa deontologia e formazione."}, {"paese": "Gabon", "registro": "https://arbitrage-iimac.com/", "background": "Mediazione commerciale presso centri come il CMA Gabon e l'IIMAC di Libreville, che accreditano i propri mediatori; si applica l'OHADA. Nessun registro pubblico unico."}, {"paese": "Gambia", "registro": "https://adrs.gm/", "background": "L'Alternative Dispute Resolution Secretariat (ADRS), presso il Ministero della Giustizia, dispone di mediatori; nominati mediatori certificati dai tribunali (avvocati e giudici) dopo formazione. Opera la Court-Connected ADR della magistratura."}, {"paese": "Georgia", "registro": "https://mediators.ge/", "background": "L'Associazione dei Mediatori della Georgia (ente di diritto pubblico, legge 2019) tiene il Registro Unico dei Mediatori; per iscriversi occorre il programma di certificazione in tre fasi dell'Associazione."}, {"paese": "Germania", "registro": "https://www.bmj.de", "background": "Nessun registro statale; chi completa la formazione può fregiarsi del titolo di zertifizierter Mediator (Mediationsgesetz e ZMediatAusbV: min. 130 ore, 5 mediazioni supervisionate, aggiornamento continuo). Le associazioni rilasciano proprie liste."}, {"paese": "Ghana", "registro": "https://judicial.gov.gh/jsweb/index.php/jsg-services/court-services/adr", "background": "ADR disciplinato dall'Alternative Dispute Resolution Act 2010 (Act 798); la Court-Connected ADR opera dal 2005 con un pool di mediatori formati. Non esiste ancora un albo nazionale obbligatorio (in progetto un database nazionale)."}, {"paese": "Giamaica", "registro": "https://www.drfja.org/", "background": "La Dispute Resolution Foundation (DRF), collegata al Ministero della Giustizia sotto il patrocinio del Chief Justice, forma e certifica i mediatori e fornisce la mediazione annessa ai tribunali dal proprio roster."}, {"paese": "Giappone", "registro": "https://www.adr.go.jp/jigyousha/", "background": "Il Ministero della Giustizia certifica gli organismi privati di ADR (sistema Kaiketsu Support, legge ADR 2004) e ne pubblica l'elenco (~170 enti). I mediatori operano in tali organismi; nella mediazione giudiziale (chōtei) i comitati includono giudici e commissari laici."}, {"paese": "Gibuti", "registro": "https://ccd.dj/", "background": "Nessun centro nazionale né registro pubblico dei mediatori online; le controversie commerciali possono essere gestite tramite conciliazione o arbitrato ad hoc. Dati affidabili non reperiti."}, {"paese": "Giordania", "registro": "https://moj.gov.jo/EN/Pages/Mediation", "background": "Legge 12/2006 sulla mediazione civile: tre categorie di mediatori (giudici-mediatori dei centri presso i tribunali, mediatori speciali nominati dal Ministro, mediatori privati designati dal Presidente del Consiglio Giudiziario)."}, {"paese": "Grecia", "registro": "https://www.diamesolavisi.gov.gr/mitrwo-diamesolavitwn", "background": "Il Ministero della Giustizia (Commissione Centrale di Mediazione) tiene il Registro dei mediatori accreditati; accreditamento con formazione presso ente riconosciuto ed esame. Il registro riporta studi, professione e ore di formazione."}, {"paese": "Grenada", "registro": "https://www.eccourts.org/court-connected-mediation", "background": "Come per gli altri Stati OECS, mediazione court-connected della Eastern Caribbean Supreme Court; mediatori formati iscritti nel Roster dell'ECSC (Practice Directions 6 e 7 del 2020)."}, {"paese": "Guatemala", "registro": "https://www.oj.gob.gt/", "background": "L'Organismo Judicial, tramite la DMASC, coordina i Centri di Mediazione; per essere mediatore occorre il corso di mediazione dell'Organismo Judicial, che tiene un'apposita banca dati."}, {"paese": "Guinea", "registro": "", "background": "Mediazione commerciale presso la Chambre d'Arbitrage de Guinée (1998); si applica l'OHADA 2017. Dal 2025 opera l'Association des Médiateurs Professionnels de Guinée (AMPG). Nessun registro pubblico online."}, {"paese": "Guinea Equatoriale", "registro": "", "background": "Membro OHADA, applica l'Atto uniforme sulla mediazione; nessun centro nazionale né registro pubblico. Una funzione conciliativa è svolta dalla Commissione ricorsi e petizioni del legislativo. Dati limitati."}, {"paese": "Guinea-Bissau", "registro": "", "background": "Membro OHADA (Atto uniforme sulla mediazione 2017); non reperibili online un registro pubblico dei mediatori né un centro nazionale dedicato."}, {"paese": "Guyana", "registro": "https://supremecourt.gy/", "background": "Le Judicature (Court Annexed Mediation) Rules prevedono court accredited mediators accreditati dal Chief Justice e registrati dal Chief Registrar; nessun elenco pubblico online."}, {"paese": "Haiti", "registro": "https://www.ccah.ht/", "background": "La Chambre de Conciliation et d'Arbitrage d'Haïti (CCAH) amministra mediazione e arbitrato commerciale; il suo Consiglio designa le persone iscritte nelle liste di arbitri e mediatori. Haiti ha firmato la Convenzione di Singapore (2019)."}, {"paese": "Honduras", "registro": "https://www.sgjd.gob.hn/quienes-somos/dependencias/subsecretaria-de-justicia/353-direccion-de-solucion-extrajudicial-de-conflictos", "background": "Conciliazione/mediazione regolata dalla Legge di Conciliazione e Arbitrato (Decreto 161-2000); i centri tengono liste di conciliatori (professionisti universitari formati dal centro). La Dirección de Solución Extrajudicial de Conflictos coordina il registro."}, {"paese": "Hong Kong", "registro": "https://www.hkmaal.org.hk/", "background": "La Hong Kong Mediation Accreditation Association (HKMAAL) è l'organismo di accreditamento e mantiene i panel (General, Family, Family Mediation Supervisor); accreditamento con formazione, valutazione e CPD."}, {"paese": "India", "registro": "https://mcpc.nic.in/", "background": "Con il Mediation Act 2023 la mediazione è regolata a livello nazionale; il Mediation Council of India dovrà registrare mediatori, enti e istituti. Oggi i mediatori sono nei panel delle Legal Services Authorities e dei comitati di mediazione delle corti (avvocati o esperti, corso ~40 ore e tirocinio)."}, {"paese": "Indonesia", "registro": "https://mahkamahagung.go.id/media/11440", "background": "Regolamento PERMA 1/2016: la mediazione giudiziaria può essere svolta da giudici o mediatori non giudici; questi ultimi devono avere un certificato di ente di formazione accreditato dalla Corte Suprema."}, {"paese": "Iran", "registro": "http://arbitration.ir/en/home/", "background": "Mediazione (میانجیگری) gestita dai Consigli di risoluzione delle controversie (شورای حل اختلاف) e dal Centro della magistratura; mediatori e arbitri selezionati per concorso nazionale e licenziati. Nessun albo pubblico online."}, {"paese": "Iraq", "registro": "", "background": "Nessuna legge organica sulla mediazione né registro nazionale; la risoluzione avviene per conciliazione giudiziaria e meccanismi tradizionali/tribali (الصلح العشائري)."}, {"paese": "Irlanda", "registro": "https://www.themii.ie/find-a-mediator/", "background": "Il Mediation Act 2017 prevede un Mediation Council non ancora istituito; il Mediators' Institute of Ireland (MII) è il principale organismo (~700 mediatori). Accreditamento con corso (≥60 ore), codice etico, CPD e assicurazione."}, {"paese": "Islanda", "registro": "https://island.is/sattamedferd-i-agreiningsmalum-vegna-barna", "background": "Nessun albo professionale; rilievo alla mediazione familiare obbligatoria (sáttameðferð) prima delle cause su affidamento, offerta dai commissari distrettuali (sýslumenn) o esperti. Poca tradizione di mediazione civile/commerciale."}, {"paese": "Isole Marshall", "registro": "", "background": "Nessun meccanismo formale di ADR né albo di mediatori; le controversie (spesso su terra e diritti consuetudinari) sono risolte dal Traditional Rights Court e dalle corti comunitarie."}, {"paese": "Isole Salomone", "registro": "", "background": "Nessun registro pubblico di mediatori; la mediazione è prevista a livello processuale (Courts Civil Procedure Rules 2007), mentre le dispute locali e fondiarie sono trattate dai chiefs e dalle Local Courts secondo la kastom."}, {"paese": "Israele", "registro": "https://www.gov.il/he/pages/mediation_department", "background": "La lista dei mediatori è pubblicata dall'Amministrazione delle Corti e dal Ministero della Giustizia (Regolamento 2017); corso professionale di ~60 ore accademiche, con corsi aggiuntivi e selezione per l'accreditamento presso i tribunali (MAHUT) e per il familiare."}, {"paese": "Italia", "registro": "https://mediazione.giustizia.it/ROM/ALBOORGANISMIMEDIAZIONE.ASPX", "background": "I mediatori operano in organismi iscritti in un registro tenuto dal Ministero della Giustizia; esistono l'elenco degli enti di formazione e quello dei formatori. Requisiti di onorabilità, corso presso ente accreditato e tirocinio (affiancamento in almeno dieci mediazioni); d.m. 24 ottobre 2023 n. 150."}, {"paese": "Kazakistan", "registro": "https://mediator.kz/reestr", "background": "Mediatore professionale: istruzione superiore, ≥25 anni, corso di formazione approvato con certificato e iscrizione nel registro di un'organizzazione di mediatori. Esistono anche i mediatori 'di comunità' (≥40 anni) iscritti presso gli organi esecutivi locali."}, {"paese": "Kenya", "registro": "https://judiciary.go.ke/court-annexed-mediation/", "background": "Il Mediation Accreditation Committee (MAC), ex sez. 59A del Civil Procedure Act, accredita i mediatori e tiene il registro da cui si nominano i mediatori per la Court-Annexed Mediation; richiesti corso di 40 ore e codice di condotta."}, {"paese": "Kirghizistan", "registro": "https://mediator.kg/mediators/", "background": "Legge sulla mediazione 256 del 14 novembre 2025: mediatore ≥25 anni con istruzione superiore, ≥80 ore di formazione, certificato e iscrizione nel Registro statale unico presso un centro; Camera dei mediatori ad adesione obbligatoria."}, {"paese": "Kiribati", "registro": "", "background": "Nessuna professione di mediatore accreditato né registro; risoluzione tramite magistrates' courts e High Court (Divisione fondiaria), con ruolo del diritto consuetudinario."}, {"paese": "Kosovo", "registro": "https://ndermjetesimi.com/", "background": "Il mediatore (ndërmjetësues) è certificato e licenziato; la professione è organizzata tramite l'Oda e Ndërmjetësuesve të Kosovës (Camera dei mediatori). Esiste un Registro pubblico dei mediatori consultabile elettronicamente, presente presso ogni ufficio di mediazione nei tribunali di base."}, {"paese": "Kuwait", "registro": "https://www.moj.gov.kw/", "background": "Il Ministero della Giustizia ha lanciato la piattaforma di mediazione 'Wasata' (وساطة) per le controversie civili e commerciali, con mediatori iscritti e specializzati; nel 2025 fissati sei requisiti per i centri privati e un onorario massimo del 5%."}, {"paese": "Laos", "registro": "", "background": "Nessun registro nazionale online. Mediazione su tre livelli: Unità di mediazione dei villaggi, ufficio per le controversie economiche del Ministero della Giustizia e mediazione dei giudici; a livello di villaggio guidata da anziani, familiari o monaci."}, {"paese": "Lesotho", "registro": "", "background": "Mediazione soprattutto come Court-Annexed Mediation (High Court Mediation Rules 2011), amministrata dall'Alta Corte tramite un Mediation Administrator; nessun elenco pubblico online, nomina nell'ambito del programma CAM."}, {"paese": "Lettonia", "registro": "https://sertificetimediatori.lv/mediatori/", "background": "Il mediatore certificato è iscritto nell'elenco del Consiglio dei mediatori certificati; certificazione con istruzione universitaria, padronanza del lettone al livello più alto ed esame in tre parti; certificato valido cinque anni."}, {"paese": "Libano", "registro": "https://www.cpm-usj.org", "background": "Il mediatore è iscritto nella lista di un centro accreditato dal Ministero della Giustizia (legge 82/2018 sulla mediazione giudiziaria; legge 286/2022 sulla mediazione convenzionale); principali centri il CPM (USJ) e il Lebanese Arbitration and Mediation Centre (Camera di Beirut)."}, {"paese": "Liberia", "registro": "", "background": "Mediazione e conciliazione riconosciute ma poco usate rispetto a giudizio e arbitrato; nessun registro nazionale pubblico né procedura di accreditamento formale online."}, {"paese": "Liechtenstein", "registro": "https://www.llv.li/serviceportal2/amtsstellen/amt-fuer-justiz/mediation/liste-der-eingetragenen-mediatoren.pdf", "background": "Mediazione civile disciplinata dallo Zivilrechts-Mediations-Gesetz (2005); elenco tenuto dall'Amt für Justiz. Richiesti 28 anni, qualifica in mediazione, affidabilità, assicurazione RC, locali idonei e cittadinanza SEE/domicilio; rinnovo con ~50 ore di formazione continua."}, {"paese": "Lituania", "registro": "https://vgtpt.lrv.lt/lt/prokurorams-tyrejams-ir-teismams/advokatu-mediatoriu-ir-psichologu-sarasai-1/lietuvos-respublikos-mediatoriu-sarasas-1/", "background": "L'elenco dei mediatori è tenuto dal Servizio di assistenza legale garantita dallo Stato (VGTPT); dal 2019 possono esercitare solo le persone che hanno superato un esame, con reputazione irreprensibile, istruzione universitaria e formazione in mediazione."}, {"paese": "Lussemburgo", "registro": "https://mj.gouvernement.lu/fr/professions-droit/mediateur-civile-commerciale.html", "background": "Il mediatore civile e commerciale è agréé dal Ministro della Giustizia, su parere del Procuratore generale (legge 24 febbraio 2012); richiesta formazione specifica (Master in mediazione o esperienza equivalente)."}, {"paese": "Macedonia", "registro": "https://www.kmrsm.org.mk/medijatori/", "background": "L'albo dei mediatori licenziati è tenuto dalla Camera dei mediatori (2017), pubblicato anche dal Ministero della Giustizia; licenza con istruzione superiore, formazione ≥70 ore, ≥3 anni di esperienza, osservazioni, test psicologico ed esame; durata cinque anni."}, {"paese": "Madagascar", "registro": "https://www.camm.mg/", "background": "Mediazione commerciale gestita dal CAMM (Centre d'Arbitrage et de Médiation de Madagascar); mediatore neutrale proposto dalle parti o designato dal Comitato del CAMM. Nessun albo pubblico ufficiale online."}, {"paese": "Malawi", "registro": "https://www.miac.mw/", "background": "Mediazione ex Mediation Act 2017 e regole di court-annexed mediation dell'Alta Corte; il Malawi International Arbitration Centre (MIAC, 2023) offre mediazione e arbitrato tramite un panel di neutrali."}, {"paese": "Maldive", "registro": "https://miac.gov.mv/", "background": "Il Maldives International Arbitration Centre (MIAC, 2021) è l'unica istituzione che offre arbitrato e mediazione, con panel di professionisti formati; mediazione istituzionale in fase iniziale, nessun albo pubblico separato."}, {"paese": "Malesia", "registro": "https://www.mimc.org.my/", "background": "Accreditamento nel panel del Malaysian International Mediation Centre (MIMC) con workshop di 56 ore (o equivalente); mediatore neutrale accreditato dal MIMC. Opera anche l'AIAC."}, {"paese": "Mali", "registro": "https://www.cecam.ml/", "background": "Controversie commerciali gestite dal CECAM (Centre de Conciliation et d'Arbitrage du Mali) presso la Camera di Commercio; conciliazione e arbitrato. Nessun requisito pubblico dettagliato di accreditamento online."}, {"paese": "Malta", "registro": "https://mediation.mt/en/civil/", "background": "Accreditamento presso il Malta Mediation Centre con Master in Mediation dell'Università di Malta o titolo equivalente, e conoscenza di inglese e maltese; il Centro tiene liste per materia (civile, famiglia, varie)."}, {"paese": "Marocco", "registro": "https://www.cmac.ma", "background": "Mediazione convenzionale disciplinata dalla legge 95.17 (in vigore dal 13 giugno 2022); il mediatore è persona fisica capace, non condannata per fatti contro l'onore, con obbligo di dichiarare cause di incompatibilità. Nessun albo pubblico unico."}, {"paese": "Mauritania", "registro": "https://cimam.net/", "background": "Il Centre International de Médiation et d'Arbitrage de Mauritanie (CIMAM), autorizzato nel 2015 e operativo dal 2019, gestisce arbitrato e mediazione delle controversie commerciali."}, {"paese": "Mauritius", "registro": "https://marc.mu/", "background": "Nessun albo statale; principale elenco quello del MARC (Camera di Commercio MCCI), aperto a chi completa il programma International Accredited Professional Mediator; in giudizio operano i giudici-mediatori della Corte Suprema (Mediation Rules 2010)."}, {"paese": "Messico", "registro": "https://www.poderjudicialcdmx.gob.mx/cja/mediacion-privada-2/", "background": "Mediazione disciplinata a livello statale: ogni Stato ha un Centro de Justicia Alternativa presso il potere giudiziario che certifica i mediatori e tiene il padrón; certificazione con requisiti di legge statale ed esame, validità triennale."}, {"paese": "Moldova", "registro": "https://justice.gov.md/ro/content/lista-mediatorilor", "background": "Legge 137/2015 sulla mediazione, coordinata dal Consiliul de Mediere presso il Ministero della Giustizia, che autorizza i mediatori e tiene il Registrul de stat al mediatorilor (corso presso enti accreditati)."}, {"paese": "Monaco", "registro": "https://monservicepublic.gouv.mc/", "background": "Nessun registro pubblico ufficiale né disciplina strutturata con albo consultabile; opera un Médiateur/ombudsman per i rapporti con l'amministrazione. Le controversie commerciali ricorrono a conciliazione giudiziaria e centri esteri."}, {"paese": "Mongolia", "registro": "https://www.judcouncil.mn/site/status_page/evleruulen", "background": "Legge sulla mediazione (2012, in vigore dal 2013): il Consiglio Generale della Magistratura seleziona, certifica e registra i mediatori tramite un Consiglio dei Mediatori; laurea in giurisprudenza o scienze sociali, corso e selezione; mediazione soprattutto annessa ai tribunali."}, {"paese": "Montenegro", "registro": "https://centarzaars.me/", "background": "Tra i primi della regione ad adottare una legge sulla mediazione (2005); il Centar za alternativno rješavanje sporova (Podgorica) gestisce accreditamento e registro dei mediatori. Possono diventarlo avvocati, assistenti sociali, psicologi, insegnanti e docenti con formazione aggiuntiva e licenza."}, {"paese": "Mozambico", "registro": "https://www.cacm.org.mz/", "background": "Quadro dato dalla Legge 11/99 (arbitrato, conciliazione e mediazione) e, per il lavoro, dalla Legge sul Lavoro 13/2023; nessun albo statale, principale ente il CACM (centro privato della CTA, Maputo) che forma e fornisce mediatori/arbitri."}, {"paese": "Myanmar", "registro": "http://miac-inc.org/", "background": "Nessuna legge organica sulla mediazione (il c.p.c. sez. 89A consente il rinvio alla conciliazione); nessun albo pubblico. Il Myanmar International Arbitration Centre (MIAC) e il centro UMFCCI offrono arbitrato e mediazione con un panel selezionato (avvocati ed esperti d'affari)."}, {"paese": "Namibia", "registro": "https://ejustice.jud.na/High%20Court/Mediation/Contact%20Details/COURT-ACCREDITED%20MEDIATOR%20PROFILES%202023.pdf", "background": "Mediazione integrata nel case management della High Court (Regole 38-39, dal 2014); il tribunale tiene un elenco di mediatori accreditati (Court-Accredited Mediator Profiles), con formazione gestita dalla Direzione della High Court."}, {"paese": "Nauru", "registro": "https://naurujudiciary.gov.nr", "background": "Nessuna legge sulla mediazione né quadro strutturato; usata soprattutto in ambito civile e familiare con rinvio a mediatori locali; prevalgono forme tradizionali (anziani, figure comunitarie e religiose); il Labour Advisory Board concilia il lavoro."}, {"paese": "Nepal", "registro": "https://mediationcouncil.gov.np/", "background": "Il Mediation Council (Melmilap Parishad), ex Mediation Act 2011, presieduto da un giudice della Corte Suprema, accredita gli enti di formazione, certifica i mediatori e tiene l'albo; requisiti: cittadinanza, ≥25 anni, laurea, corso ~40 ore, rinnovo triennale."}, {"paese": "Nicaragua", "registro": "https://www.poderjudicial.gob.ni/dirac22/mediadores.asp", "background": "La DIRAC (Potere Giudiziario) accredita e vigila i centri ADR e tiene il registro di mediatori, conciliatori e arbitri (Legge 540); definisce le condizioni tecniche e accademiche per la certificazione e un codice etico."}, {"paese": "Niger", "registro": "https://www.cman.ne/", "background": "Membro OHADA; il Centre de Médiation et d'Arbitrage de Niamey (CMAN) della Camera di Commercio gestisce mediatori e arbitri iscritti. Da distinguere dal Médiateur de la République (ombudsman)."}, {"paese": "Nigeria", "registro": "https://lagosmultidoor.org.ng/", "background": "Mediazione court-connected gestita dai Multi-Door Courthouses (primo il Lagos Multi-Door Courthouse, 2002/2007), con panel di mediatori accreditati approvato dal Chief Judge; accreditamento anche da NICArb e Institute of Chartered Mediators and Conciliators (laurea, ottimo inglese, aggiornamento)."}, {"paese": "Norvegia", "registro": "https://www.bufdir.no/familie/samlivsbrudd/mekling/eksterne-meklere/", "background": "Mediazione familiare gestita dal servizio pubblico (uffici di protezione della famiglia) e da mediatori esterni approvati dal Bufdir; esiste inoltre il Konfliktrådet (Ministero della Giustizia) con ~550 mediatori volontari per la giustizia riparativa."}, {"paese": "Nuova Zelanda", "registro": "https://www.justice.govt.nz/about/lawyers-and-service-providers/service-providers/family-mediation-and-parenting-course-providers/", "background": "Mediatori formati e accreditati da AMINZ e Resolution Institute; requisito base un corso introduttivo di cinque giorni, scala fino a Fellow e aggiornamento continuo. Il Ministero della Giustizia pubblica l'elenco dei fornitori di mediazione familiare."}, {"paese": "Oman", "registro": "https://omanarbitration.om/", "background": "L'Oman Commercial Arbitration Centre (OAC, Decreto Reale 36/2018) offre arbitrato e mediazione (regole 2021); nessun albo pubblico obbligatorio, l'OAC propone una lista di candidati mediatori qualificati."}, {"paese": "Paesi Bassi", "registro": "https://mfnregister.nl/", "background": "I mediatori sono iscritti al MfN-register, registro nazionale di qualità della Mediatorsfederatie Nederland; per il titolo di MfN-registermediator: formazione riconosciuta, test di conoscenza, assessment pratico e aggiornamento continuo. Gli enti pubblici collaborano solo con iscritti."}, {"paese": "Pakistan", "registro": "https://www.micadr.com/accredited-mediator-2/", "background": "Accreditamento ex ADR Mediation Accreditation (Eligibility) Rules 2023 (ADR Act 2017): il mediatore deve essere formato e certificato da organizzazioni elencate nell'allegato; possibile anche tramite centri ADR riconosciuti; requisiti aggiuntivi delle alte corti per le mediazioni disposte dal giudice."}, {"paese": "Palau", "registro": "http://palaucourts.gov.pw", "background": "La magistratura gestisce un programma di mediazione/ADR tramite workshop e formazione dei formatori; nessun registro ufficiale online né sistema formale di accreditamento consultabile."}, {"paese": "Palestina", "registro": "https://www.palmedarb.org", "background": "La mediazione è riconosciuta come metodo legittimo, spesso raccomandata nelle cause civili; servizi offerti soprattutto da ONG e da professionisti dell'Ordine degli avvocati. Nessun registro pubblico unico."}, {"paese": "Panama", "registro": "https://www.panamadigital.gob.pa/InformacionTramite/registro-de-mediadores-y-conciliadores", "background": "Per esercitare occorre formazione in mediazione di almeno 40 ore certificata e iscrizione presso un centro, oltre all'assenza di condanne; la certificazione va iscritta nel Registro dei conciliatori e mediatori del Ministerio de Gobierno (DRAC)."}, {"paese": "Papua Nuova Guinea", "registro": "https://www.pngjudiciary.gov.pg/index.php/national-court/civil-cases/adr", "background": "Accreditamento ex ADR Rules 2022, che istituiscono un Mediator Accrediting Council e un codice di condotta; mediazioni annesse ai tribunali condotte da mediatori accreditati (giudici, avvocati ed esperti) nominati dal tribunale dall'elenco degli accreditati."}, {"paese": "Paraguay", "registro": "https://www.pj.gov.py/contenido/150-direccion-de-mediacion/1198", "background": "Iscrizione regolata dalle Acordadas della Corte Suprema; prima di esercitare occorre un corso presso un Centro di Mediazione di almeno 100 ore accademiche ed esame scritto, orale e pratico. Registro tenuto dalla Dirección de Mediación del Poder Judicial."}, {"paese": "Perù", "registro": "https://www.gob.pe/794-inscribete-como-conciliador-extrajudicial-acreditado", "background": "La figura è il conciliatore extragiudiziale, accreditato e iscritto nel registro del Ministero della Giustizia (MINJUSDH) tramite la Dirección de Conciliación Extrajudicial; necessario il Corso di Conciliazione Extragiudiziale del MINJUSDH o di centri autorizzati."}, {"paese": "Polonia", "registro": "https://krm.gov.pl/", "background": "Esistono il Krajowy Rejestr Mediatorów (nazionale) e le liste dei mediatori permanenti tenute dai presidenti dei tribunali circondariali; il mediatore permanente deve avere ≥26 anni, conoscere il polacco, non avere condanne dolose e possedere competenze documentate."}, {"paese": "Portogallo", "registro": "https://dgpj.justica.gov.pt/Resolucao-de-Litigios/Mediacao/Lista-de-mediadores-privados", "background": "Il Ministério da Justiça (DGPJ) gestisce i sistemi pubblici di mediazione e pubblica la lista dei mediatori privati e gli elenchi dei sistemi pubblici (familiare, penale, laboristica, giudici di pace); iscrizione con corso presso ente riconosciuto dalla DGPJ."}, {"paese": "Qatar", "registro": "https://www.qicdrc.gov.qa/services/mediation", "background": "Mediazione regolata dalla Legge 20/2021; il mediatore deve avere piena capacità, buona reputazione, imparzialità ed esperienza. Controversie assegnabili a mediatori del panel del Qatar International Court and Dispute Resolution Centre (QICDRC); diffuso l'accreditamento IMI."}, {"paese": "Regno Unito (Inghilterra e Galles)", "registro": "https://civilmediation.org", "background": "Registro del Civil Mediation Council (CMC): corso accreditato (4-5 giorni) e punti di osservazione/esperienza; livelli Associate, Registered e Fellow, con assicurazione, CPD e codice di condotta. Nessun requisito di provenienza professionale."}, {"paese": "Regno Unito (Irlanda del Nord)", "registro": "https://mediatorsni.co.uk", "background": "Nessun registro statale unico: la Law Society of NI gestisce un panel di mediatori accreditati e il Bar of NI una directory; accreditamento tramite CEDR, Law Society NI, Family Mediation NI o il MII (corso ~60 ore ed esame)."}, {"paese": "Regno Unito (Scozia)", "registro": "https://www.scottishmediation.org.uk", "background": "Registro ufficiale lo Scottish Mediation Register, gestito da Scottish Mediation; corso accreditato (~5 giorni), numero minimo di mediazioni e ore, con CPD e copertura assicurativa annuale."}, {"paese": "Repubblica Ceca", "registro": "https://mediace.justice.cz", "background": "Il Ministero della Giustizia tiene il seznam mediátorů (mediatori registrati, zapsaný mediátor); requisiti: capacità, integrità, laurea ed esame di mediatore (prova scritta e orale). Lista distinta di mediatori familiari."}, {"paese": "Repubblica Centrafricana", "registro": "https://www.ohada.org", "background": "Membro OHADA: mediazione ex Atto uniforme (2017, in vigore dal 2018); nessun registro nazionale pubblico online, accreditamento tramite centri e programmi di formazione dello spazio OHADA."}, {"paese": "Repubblica Democratica del Congo", "registro": "http://www.cenacom.cd", "background": "Membro OHADA; istituzione principale il CENACOM (Kinshasa) per arbitrato, conciliazione, mediazione e formazione; opera anche il CRAD. Accreditamento tramite programmi di certificazione OHADA in mediazione commerciale."}, {"paese": "Repubblica Dominicana", "registro": "https://poderjudicial.gob.do/servicio-de-mediacion-del-poder-judicial-celebra-20-anos-promoviendo-la-paz-social-a-traves-del-dialogo/", "background": "Mediazione gestita dal Servizio di Mediazione del Poder Judicial (con centri come il CEMEFA), ex Ley 181-09 e Regolamento MARC 2018; mediatori giudiziari formati e accreditati dalla Escuela Nacional de la Judicatura. Nessun elenco pubblico online dei singoli mediatori."}, {"paese": "Romania", "registro": "https://consiliuldemediere.ro/tabloul-mediatorilor", "background": "Professione regolata dalla Legge 192/2006; mediatore autorizzato con corso presso ente accreditato e iscrizione nel Tabloul mediatorilor tenuto dal Consiliul de Mediere; accesso aperto a laureati di vari settori."}, {"paese": "Ruanda", "registro": "https://www.minijust.gov.rw/services/mediation-committees-abunzi", "background": "Mediazione comunitaria affidata ai comitati Abunzi (legge 2006), a livello di cellula e settore; 7 residenti di integrità eletti per 5 anni (≥30% donne), volontari e gratuiti. Introdotti anche mediatori giudiziari."}, {"paese": "Russia", "registro": "https://rosreestr.gov.ru/site/ur/vnesenie-svedeniy-v-edinyy-gosudarstvennyy-reestr-samoreguliruemykh-organizatsiy-mediatorov/", "background": "Mediazione ex Legge federale 193-FZ (2010); mediatore professionista ≥25 anni, istruzione superiore e corso di formazione; su base non professionale maggiorenni capaci senza precedenti. Rosreestr tiene il registro statale delle SRO di mediatori."}, {"paese": "Saint Kitts e Nevis", "registro": "https://www.eccourts.org/court-connected-mediation", "background": "Court-Connected Mediation della Eastern Caribbean Supreme Court (progetto JURIST); mediatori formati dall'istituto giudiziario dell'ECSC e inseriti in un roster (anche regionale). Nessun elenco pubblico online dei singoli."}, {"paese": "Saint Vincent e Grenadine", "registro": "https://www.eccourts.org/court-connected-mediation", "background": "Mediazione sotto la Eastern Caribbean Supreme Court (Practice Directions 2020, CPR 2000); mediatori formati dall'ECSC in un roster della High Court, con mediazione pre-causa. Nessun elenco pubblico online dei singoli."}, {"paese": "Samoa", "registro": "https://www.mjca.gov.ws/", "background": "Mediazione ex Alternative Disputes Resolution Act 2007, gestita dal Court Annexed Mediation Unit del Ministry of Justice and Courts Administration; mediatori accreditati ('Tufuga o Faatofalaiga') riuniti nell'AMSA. Restano i Village Fono per il consuetudinario."}, {"paese": "San Marino", "registro": "", "background": ""}, {"paese": "Santa Lucia", "registro": "https://www.eccourts.org/court-connected-mediation", "background": "Mediazione gestita dalla Registry della Eastern Caribbean Supreme Court (Saint Lucia), obbligatoria prima del giudizio per molte cause civili; Roster of Mediators dell'ECSC con professionisti di vari settori formati e accreditati dalla Corte."}, {"paese": "Senegal", "registro": "https://arbitrage-senegal.com/liste-des-mediateurs/", "background": "Principale organismo il CAMC (Camera di Commercio di Dakar), con una lista di mediatori e conciliatori qualificati; nessun diploma di Stato, accesso tramite formazione specialistica (es. EPMN Africa, ~50-200 ore). Provenienza giuridica, economica o d'impresa."}, {"paese": "Serbia", "registro": "https://mpravde.gov.rs/registar-posrednika", "background": "I mediatori (posrednici) devono ottenere una licenza (Legge sulla mediazione 2014) ed essere iscritti nel Registro dei mediatori del Ministero della Giustizia; formazione base da organismi autorizzati; esiste anche la Camera dei mediatori (KMS)."}, {"paese": "Seychelles", "registro": "https://www.judiciary.sc", "background": "Mediazione giudiziale ex Supreme Court (Mediation) Rules 2013; il giudice può rinviare la causa e nominare il mediatore. Nessun albo/registro pubblico online né requisiti dettagliati; nomina caso per caso sotto la Registry."}, {"paese": "Sierra Leone", "registro": "", "background": "ADR imperniato sulla Fast Track Commercial Court (2010) e sull'Arbitration Act 2022 (che prevede il SLIAC); nessun registro pubblico online dei mediatori né sistema formale di accreditamento consultabile."}, {"paese": "Singapore", "registro": "https://www.simi.org.sg/What-We-Offer/Finding-a-suitable-Mediator/List-of-SIMI-Accredited-Mediators-Level-1", "background": "Standard definiti dal Singapore International Mediation Institute (SIMI), che tiene un registro pubblico di mediatori accreditati su più livelli; formazione e valutazione da provider come il Singapore Mediation Centre (SMC), con moduli SCMP e Mediation Skills Assessment; rinnovo con formazione continua."}, {"paese": "Slovacchia", "registro": "https://www.justice.gov.sk/registre/mediatori/", "background": "Il Ministero della Giustizia tiene il registro dei mediatori, dei centri e degli enti di formazione (Legge 420/2004); iscrizione con laurea, certificato di formazione ed esame di mediatore e onorabilità."}, {"paese": "Slovenia", "registro": "https://spvt.mp.gov.si/centralna-evidenca-mediatorjev-ki-delujejo-v-programih-sodisc/", "background": "Il Ministero della Giustizia gestisce la Centralna evidenca mediatorjev per i programmi dei tribunali (legge ZARSS); iscrizione con almeno una laurea e corso secondo il programma ministeriale; ≥12 ore di formazione continua l'anno."}, {"paese": "Somalia", "registro": "https://www.idlo.int/", "background": "Nessun registro pubblico online; mediazione tramite gli 'ADR Centers' del Ministero della Giustizia federale (dal 2014) e il sistema consuetudinario Xeer (consigli di anziani, odayaal); roster selezionato tra anziani, sheikh, donne e imprenditori noti per onestà e imparzialità."}, {"paese": "Spagna", "registro": "https://www.mjusticia.gob.es/es/ciudadania/registros/mediadores-instituciones", "background": "Il Registro de Mediadores e Instituciones de Mediación del Ministerio de Justicia è pubblico e gratuito online; per iscriversi: pieno esercizio dei diritti civili, titolo universitario o di formazione professionale superiore, formazione specifica ≥100 ore e assicurazione RC."}, {"paese": "Sri Lanka", "registro": "https://mediation.gov.lk/en/", "background": "Programma gestito dalla Mediation Boards Commission col Ministero della Giustizia; oltre 8.600 mediatori volontari formati dai Mediator Training Officers e operanti nei 329 Community Mediation Boards."}, {"paese": "Stati Federati di Micronesia", "registro": "https://www.fsmsupremecourt.org", "background": "Nessun registro pubblico ufficiale; mediazione e ADR nell'ambito della Supreme Court della FSM e delle corti statali (Kosrae, Pohnpei…), senza criteri formali di accreditamento o elenco ufficiale online."}, {"paese": "Stati Uniti", "registro": "https://drc.flcourts.org/", "background": "Nessun albo nazionale: qualifiche regolate a livello statale tramite roster delle corti, statuti e organismi privati (ACR, NAM). Requisiti variabili (dalle 18 ore del New Jersey alle 100 ore del Maine); in Florida certificazione della Corte Suprema tramite il Dispute Resolution Center."}, {"paese": "Sud Sudan", "registro": "", "background": "Nessun registro ufficiale né legge specifica; quadro basato sull'Arbitration Act 2000 e sul c.p.c.; mediazione comunitaria (Community Mediation Groups) su base consuetudinaria, spesso su questioni fondiarie."}, {"paese": "Sudafrica", "registro": "https://www.justice.gov.za/mediation/mediation.html", "background": "Nella court-annexed mediation (Rule 41A / Magistrates' Courts) i mediatori sono scelti da un panel accreditato nominato dal Ministro; accreditamento professionale gestito dal DiSAC (Dispute Settlement Accreditation Council), con corso accreditato e rinnovo ogni 24 mesi."}, {"paese": "Sudan", "registro": "", "background": "Nessun registro ufficiale online né obbligo legale di mediazione; i giudici possono suggerirla o disporla. Esistono istituzioni private (Sudanese Centre for Conciliation & Arbitration), ma non un quadro pubblico di licenze."}, {"paese": "Suriname", "registro": "", "background": "Mediazione agli inizi, nessun registro pubblico ufficiale; progetti in corso (Mediationgroep Suriname, con enti olandesi) per formare mediatori e istituire un registro; il pubblico ministero avvia un Mediation Bureau per la mediazione penale."}, {"paese": "Svezia", "registro": "https://www.domstol.se/om-sveriges-domstolar/for-dig-som-aktor-i-domstol/for-dig-som-medlare/forteckning-over-sarskilda-medlare/", "background": "Nessun accreditamento formale: il Domstolsverket tiene un elenco di persone disponibili come mediatori (särskild medling) nelle cause civili, basato sulle informazioni fornite dagli stessi; organizzato per regione, esclude la mediazione familiare."}, {"paese": "Svizzera", "registro": "https://www.mediation-ch.org/mediation/mediatorensuche", "background": "Professione privata regolata dalle associazioni: la FSM/SDM, organizzazione mantello nazionale, riconosce oltre 800 mediatori con formazione conforme ai suoi standard, deontologia e aggiornamento; specializzazioni familiare, commerciale, aziendale e penale."}, {"paese": "Tagikistan", "registro": "", "background": "Nessuna legge specifica né registro ufficiale; lavori legislativi in corso con supporto internazionale. Esiste un Centro di mediazione presso la Camera di commercio e industria (IDLO, BERS) per il commerciale."}, {"paese": "Taiwan", "registro": "https://www.judicial.gov.tw/tw/lp-1945-1-10-60.html", "background": "I comitati di conciliazione comunali (鄉鎮市調解委員會) sono composti da persone con competenze giuridiche o professionali, integre, proposte dal sindaco e vagliate da tribunale e procura (mandati di 4 anni, ≥1/4 donne); lo Yuan giudiziario pubblica gli elenchi dei conciliatori."}, {"paese": "Tanzania", "registro": "https://tanzlii.org/akn/tz/act/gn/2021/147/eng@2021-01-29", "background": "I mediatori sono accreditati e iscritti in un registro tenuto dal Registrar ex Reconciliation, Negotiation, Mediation and Arbitration (Practitioners Accreditation) Regulations 2021; per la court-annexed mediation il registro è tenuto dal Registrar dell'Alta Corte (≥5 anni di esperienza o avvocato con pratica)."}, {"paese": "Thailandia", "registro": "https://www.rlpd.go.th/pcd", "background": "Ex Dispute Mediation Act B.E. 2562 (2019), il 'ผู้ไกล่เกลี่ย' è iscritto nell'apposito registro e nominato per la mediazione, con requisiti stabiliti; vigilanza e registro spettano al Dipartimento per la protezione dei diritti del Ministero della Giustizia."}, {"paese": "Timor Est", "registro": "", "background": "Nessun registro ufficiale online; la mediazione è prevista nel quadro processuale e i mediatori sono soggetti a incompatibilità (non possono esercitare contemporaneamente l'avvocatura)."}, {"paese": "Togo", "registro": "https://cato.tg/", "background": "Mediazione-conciliazione gestita dalla Cour d'Arbitrage du Togo (CATO), con mediatori scelti tra avvocati del foro di Lomé, esperti contabili, magistrati, professori e ingegneri; anche le Maisons de Justice offrono mediazione."}, {"paese": "Tonga", "registro": "http://www.justice.gov.to/supreme-court/", "background": "Nessuna fonte affidabile online: la mediazione è gestita in modo informale tramite processi consuetudinari/di villaggio e i meccanismi dell'Assemblea legislativa, senza registro ufficiale."}, {"paese": "Trinidad e Tobago", "registro": "http://www.ttlawcourts.org/mediation", "background": "Mediazione ex Mediation Act 8/2004: il Mediation Board certifica i mediatori e accredita i programmi di formazione, tenendo appositi registri; i certificati possono candidarsi al roster della court-annexed mediation."}, {"paese": "Tunisia", "registro": "https://www.ccat.org.tn", "background": "Nessun registro pubblico unico; il mediatore non ha uno statuto professionale definito e una legge organica è in preparazione. Esistono figure settoriali (médiateur administratif, mediatori bancari) e un emergente statuto di mediatore familiare."}, {"paese": "Turchia", "registro": "https://adb.adalet.gov.tr/Home/arabuluculistesi/", "background": "Il registro ufficiale (Arabulucular Sicili) è tenuto dalla Direzione Generale per la Mediazione del Ministero della Giustizia; iscrizione con cittadinanza turca, laurea in Giurisprudenza, ≥5 anni di anzianità, formazione ed esame ministeriale."}, {"paese": "Turkmenistan", "registro": "", "background": "Nessuna legge specifica né registro ufficiale; nella pratica forme tradizionali di conciliazione senza mediatori professionali; solo iniziative formative internazionali."}, {"paese": "Tuvalu", "registro": "", "background": "Nessuna legge né organismo che disciplini la mediazione professionale; le controversie locali (fondiarie e familiari) sono trattate dalle Island Courts secondo il diritto consuetudinario e la mediazione tradizionale."}, {"paese": "Ucraina", "registro": "http://namu.com.ua/ua/members/", "background": "La Legge 'Sulla mediazione' (2021) prevede registri tenuti dalle associazioni e resi pubblici (nessun registro statale unico); mediatore ≥18 anni con istruzione superiore/professionale e formazione base (~90 ore). Registro più rappresentativo quello della NAMU."}, {"paese": "Uganda", "registro": "https://judiciary.go.ug", "background": "Mediazione ex Judicature (Court Annexed Mediation) Rules: solo i mediatori accreditati dalla Magistratura possono condurla; la Judiciary tiene un registro degli accreditati (formazione approvata, codice di condotta, aggiornamento). Opera anche il CADER."}, {"paese": "Ungheria", "registro": "https://inyr.im.gov.hu/mediators/name-search", "background": "Il mediatore deve essere iscritto al registro nazionale (közvetítői névjegyzék) tenuto dal Ministero della Giustizia (legge LV/2002); richiesti titolo superiore, formazione specialistica ed esperienza; attività riservata agli iscritti."}, {"paese": "Uruguay", "registro": "https://www.poderjudicial.gub.uy/institucional/centros-de-mediacion", "background": "Mediazione prevalentemente pubblica, gestita dai Centri di Mediazione del Potere Giudiziario; mediatori funzionari nominati per concorso pubblico. Nessun albo pubblico online di mediatori privati accreditati."}, {"paese": "Uzbekistan", "registro": "https://minjust.uz/uz/interactive/mediatory/", "background": "Il mediatore professionale deve avere istruzione superiore, corso secondo il programma del Ministero della Giustizia, esame di qualifica e iscrizione nel Registro dei mediatori professionali (Ris. Gabinetto dei Ministri 544/2023)."}, {"paese": "Vanuatu", "registro": "https://courts.gov.vu", "background": "Mediazione prevista dalle norme di procedura civile (Part 10) e dall'Ombudsman Act; nessun registro ufficiale pubblico online; formazione sviluppata con l'ILO e accreditamento tramite il Resolution Institute neozelandese."}, {"paese": "Venezuela", "registro": "https://cedca.org.ve/", "background": "Mediazione riconosciuta a livello costituzionale (art. 258 Cost.) ma senza legge organica; nessun registro ufficiale nazionale né requisiti professionali definiti a livello statale."}, {"paese": "Vietnam", "registro": "https://bttp.moj.gov.vn/portal/trang-chu.html", "background": "Mediazione commerciale ex Decreto 22/2017/NĐ-CP; il mediatore (hòa giải viên) deve avere titolo universitario ed esperienza; organizzazioni e mediatori 'vụ việc' autorizzati e registrati dal Ministero della Giustizia e dai Dipartimenti provinciali, che pubblicano gli elenchi."}, {"paese": "Zambia", "registro": "https://judiciaryzambia.com/court-annexed-mediation-mediators-biographies/", "background": "Mediazione court-annexed ex High Court Rules; richiesta esperienza professionale ≥5 anni e formazione/certificazione; la lista dei mediatori accreditati è tenuta dalla Magistratura, sotto il Comitato consultivo del Chief Justice."}, {"paese": "Zimbabwe", "registro": "https://www.jsc.org.zw/", "background": "Mediazione court-annexed introdotta (Statutory Instrument 2019) sotto la Judicial Service Commission; i mediatori devono essere accreditati e formati. Nessuna lista pubblica ufficiale online."}];
